"""Real signed history plus explicit policy preview remains offline without private keys."""
from pathlib import Path
import sys,json,subprocess,re
from wireledger.ledger import initialize,load_private,append
root=Path(sys.argv[1]);w=root/'w';initialize(w);append(w/'observations.jsonl',load_private(w/'witness.key'),{'host':'localhost','status':'error','error':'PRIVATE_DIAGNOSTIC'});(w/'witness.key').unlink();policy=root/'policy.json';policy.write_text(json.dumps([{'host':'LOCALHOST.','port':443,'vantage':'review'},{'host':'example.test','port':8443,'vantage':'other'}]));before={p:p.read_bytes()for p in w.iterdir()if p.is_file()};base=[sys.executable,'-m','wireledger','observe-policy',str(w),'--expected',str(policy),'--preview','--ca-file','PRIVATE_MISSING_CA'];r=subprocess.run(base,capture_output=True,text=True);assert r.returncode==0,r.stderr;value=json.loads(r.stdout);assert value['history_records']==1 and value['selected_endpoints']==2;h=subprocess.run(base+['--html'],capture_output=True,text=True);assert h.returncode==0,h.stderr;assert 'PRIVATE_DIAGNOSTIC'not in h.stdout and 'PRIVATE_MISSING_CA'not in h.stdout;assert json.loads(re.search(r'<script id="report-data" type="application/json">(.*?)</script>',h.stdout,re.S).group(1))==value;(root/'preview.html').write_text(h.stdout);(root/'preview.json').write_text(json.dumps(value));assert all(p.read_bytes()==raw for p,raw in before.items())
code="from unittest.mock import patch;from wireledger.__main__ import main\nwith patch('wireledger.collection.observe',side_effect=RuntimeError('network forbidden')),patch('wireledger.collection.load_private',side_effect=RuntimeError('key forbidden')):raise SystemExit(main())";r=subprocess.run([sys.executable,'-c',code,*base[3:],'--html'],capture_output=True);assert r.returncode==0,r.stderr
bad=subprocess.run([sys.executable,'-m','wireledger','observe-policy','missing','--expected','missing','--html'],capture_output=True,text=True);assert bad.returncode==1 and not bad.stdout and 'requires --preview'in bad.stderr
(w/'observations.jsonl').write_text('corrupt signed history\n');bad=subprocess.run(base+['--html'],capture_output=True);assert bad.returncode==1 and not bad.stdout
